import catalogue from './catalogue.json';

/**
 * Which families Google Fonts serves, read from the snapshot this package ships (ADR 0120).
 *
 * **Bundled, never fetched.** A render on an offline machine still knows CircularXX is not
 * Google's, so it says so instead of trying; and a change to the list is a reviewed diff,
 * regenerated by `tools/google-fonts-catalogue`. The snapshot's date is in the file.
 */

export type GoogleLicence = 'ofl' | 'apache' | 'ufl';

export interface GoogleFamily {
  /** Google's spelling, which is what `css2` is asked for. */
  readonly family: string;
  readonly category: string;
  readonly licence: GoogleLicence;
  /** Google's style keys: `400`, `700i`… */
  readonly styles: ReadonlySet<string>;
}

/** The day the snapshot was taken. */
export const CATALOGUE_DATE: string = catalogue.generated;

/** Compared the way the source cache compares a family: no case, no spaces or punctuation. */
export function familyKey(family: string): string {
  return family.toLowerCase().replace(/[^a-z0-9]/gu, '');
}

const byKey: ReadonlyMap<string, GoogleFamily> = new Map(
  catalogue.families.map((entry) => [
    familyKey(entry.family),
    {
      family: entry.family,
      category: entry.category,
      licence: entry.licence as GoogleLicence,
      styles: new Set(entry.styles.split(' ')),
    },
  ]),
);

/** Every family, in Google's spelling: what the `font-source` declares it serves. */
export const GOOGLE_FAMILIES: readonly string[] = catalogue.families.map((entry) => entry.family);

/** The family as Google serves it, or `undefined` for one it does not. */
export function googleFamily(family: string): GoogleFamily | undefined {
  return byKey.get(familyKey(family));
}

/** Google's key for a face: `700`, or `700i` for italic. */
export function styleKey(weight: number, style: 'normal' | 'italic'): string {
  return `${String(weight)}${style === 'italic' ? 'i' : ''}`;
}
